"""
Discover and set flight modes at runtime.

 The modes are queried from the vehicle using the MAVLink standard modes
 protocol (AVAILABLE_MODES, CURRENT_MODE). For autopilots that don't
 implement it, a list of known modes is used as a fallback.

 Modes are identified by name. Standard modes have a fixed name, e.g.
 "Position" or "Mission", other modes use the name reported by the vehicle.
 Setting a mode works the same way for both.
"""

import ctypes
import threading

from typing import Callable, Any
from enum import IntEnum

from ...cmavsdk_loader import _cmavsdk_lib
from ...exceptions import MavsdkError


# ===== Enums =====


# ===== Result Enums =====
class ModesResult(IntEnum):
    """Possible results returned for mode requests."""

    UNKNOWN = 0
    SUCCESS = 1
    NO_SYSTEM = 2
    CONNECTION_ERROR = 3
    BUSY = 4
    DENIED = 5
    UNSUPPORTED = 6
    TIMEOUT = 7
    FAILED = 8
    MODE_NOT_FOUND = 9
    MODES_NOT_KNOWN_YET = 10


class ModesError(MavsdkError):
    """Raised when a Modes request fails.

    Attributes
    ----------
    result : ModesResult
        The result the request failed with.
    origin : str
        The method that failed.
    params : tuple
        The arguments the method was called with.
    """

    def __init__(self, result, origin, *params):
        super().__init__(result, origin, *params)
        self.result = result
        self.origin = origin
        self.params = params

    def __str__(self):
        return f"{self.result.name}; origin: {self.origin}; params: {self.params}"


# ===== Internal C Structures =====
class ModeCStruct(ctypes.Structure):
    """
    Internal C structure for Mode.
    Used only for C library communication.
    """

    _fields_ = [
        ("name", ctypes.c_char_p),
        ("custom_mode", ctypes.c_uint32),
        ("is_standard", ctypes.c_bool),
        ("is_user_selectable", ctypes.c_bool),
        ("is_advanced", ctypes.c_bool),
        ("is_auto_mode", ctypes.c_bool),
    ]


# ===== Structures =====
class Mode:
    """
    Mode type.
    """

    def __init__(
        self,
        name=None,
        custom_mode=None,
        is_standard=None,
        is_user_selectable=None,
        is_advanced=None,
        is_auto_mode=None,
    ):
        self.name = name if name is not None else ""
        self.custom_mode = custom_mode if custom_mode is not None else 0
        self.is_standard = is_standard if is_standard is not None else False
        self.is_user_selectable = (
            is_user_selectable if is_user_selectable is not None else False
        )
        self.is_advanced = is_advanced if is_advanced is not None else False
        self.is_auto_mode = is_auto_mode if is_auto_mode is not None else False

    @classmethod
    def from_c_struct(cls, c_struct):
        """Convert from C structure to Python object"""
        instance = cls()
        instance.name = c_struct.name.decode("utf-8")
        instance.custom_mode = c_struct.custom_mode
        instance.is_standard = c_struct.is_standard
        instance.is_user_selectable = c_struct.is_user_selectable
        instance.is_advanced = c_struct.is_advanced
        instance.is_auto_mode = c_struct.is_auto_mode
        return instance

    def to_c_struct(self):
        """Convert to C structure for C library calls"""
        c_struct = ModeCStruct()
        c_struct.name = self.name.encode("utf-8")
        c_struct.custom_mode = self.custom_mode
        c_struct.is_standard = self.is_standard
        c_struct.is_user_selectable = self.is_user_selectable
        c_struct.is_advanced = self.is_advanced
        c_struct.is_auto_mode = self.is_auto_mode
        return c_struct

    def __str__(self):
        fields = []
        fields.append(f"name={self.name}")
        fields.append(f"custom_mode={self.custom_mode}")
        fields.append(f"is_standard={self.is_standard}")
        fields.append(f"is_user_selectable={self.is_user_selectable}")
        fields.append(f"is_advanced={self.is_advanced}")
        fields.append(f"is_auto_mode={self.is_auto_mode}")
        return f"Mode({', '.join(fields)})"


# ===== Plugin =====
class Modes:
    """Discover and set flight modes at runtime.

    The modes are queried from the vehicle using the MAVLink standard modes
    protocol (AVAILABLE_MODES, CURRENT_MODE). For autopilots that don't
    implement it, a list of known modes is used as a fallback.

    Modes are identified by name. Standard modes have a fixed name, e.g.
    "Position" or "Mission", other modes use the name reported by the vehicle.
    Setting a mode works the same way for both."""

    def __init__(self, system):
        self._lib = _cmavsdk_lib
        self._handle = None
        self._callbacks = []  # Keep references to prevent GC
        # Stream subscriptions, by handle: the trampoline to keep alive and the
        # unsubscribe to call for it. destroy() releases whatever is left. Entries
        # are taken under the lock below, so a handle goes to either destroy() or
        # one unsubscribe, never both. The C call then happens outside the lock,
        # which waits for a running callback -- and a callback may unsubscribe.
        self._subscriptions = {}
        # destroy() can be reached from any thread: explicitly, from the owner
        # tearing down, or from __del__ whenever the garbage collector happens to
        # run. Without this lock two of them can both find a live handle and
        # destroy the same plugin twice, which corrupts the heap.
        self._destroy_lock = threading.Lock()

        if system is None:
            raise ValueError("system cannot be None")

        system_handle = system._handle

        if not system_handle:
            raise ValueError("system handle is null")

        self._handle = self._lib.mavsdk_modes_create(system_handle)

        if not self._handle:
            raise RuntimeError(
                "Failed to create Modes plugin - C function returned null handle"
            )

        system._track_plugin(self)

    def subscribe_available_modes(self, callback: Callable, user_data: Any = None):
        """Subscribe to the list of available modes.

        The list is updated whenever the vehicle reports that its modes have changed."""

        def c_callback(c_data, size, ud):
            try:
                py_data = []
                if c_data and size > 0:
                    for i in range(size):
                        py_data.append(Mode.from_c_struct(c_data[i]))

                self._lib.mavsdk_modes_mode_array_destroy(ctypes.byref(c_data), size)

                callback(py_data, user_data)

            except Exception as e:
                print(f"Error in available_modes callback: {e}")

        cb = AvailableModesCallback(c_callback)

        _subscription = self._lib.mavsdk_modes_subscribe_available_modes(
            self._require_handle(), cb, None
        )

        self._subscriptions[_subscription] = (
            cb,
            self._lib.mavsdk_modes_unsubscribe_available_modes,
        )

        return _subscription

    def unsubscribe_available_modes(self, handle: ctypes.c_void_p):
        """Unsubscribe from available_modes

        Idempotent. Does nothing once the plugin is destroyed, which unsubscribes
        already.
        """
        with self._destroy_lock:
            if not self._handle:
                return
            # Holds the callback trampoline until the C unsubscribe has returned.
            _entry = self._subscriptions.pop(handle, None)
            if _entry is None:
                return
            _plugin_handle = self._handle

        self._lib.mavsdk_modes_unsubscribe_available_modes(_plugin_handle, handle)
        del _entry

    def available_modes(self):
        """Get available_modes (blocking)"""

        result_ptr = ctypes.POINTER(ModeCStruct)()
        size = ctypes.c_size_t()

        self._lib.mavsdk_modes_available_modes(
            self._require_handle(), ctypes.byref(result_ptr), ctypes.byref(size)
        )

        py_result = [Mode.from_c_struct(result_ptr[i]) for i in range(size.value)]
        self._lib.mavsdk_modes_mode_array_destroy(ctypes.byref(result_ptr), size)
        return py_result

    def subscribe_current_mode(self, callback: Callable, user_data: Any = None):
        """Subscribe to the current mode."""

        def c_callback(c_data, ud):
            try:
                py_data = Mode.from_c_struct(c_data)

                self._lib.mavsdk_modes_mode_destroy(ctypes.byref(c_data))

                callback(py_data, user_data)

            except Exception as e:
                print(f"Error in current_mode callback: {e}")

        cb = CurrentModeCallback(c_callback)

        _subscription = self._lib.mavsdk_modes_subscribe_current_mode(
            self._require_handle(), cb, None
        )

        self._subscriptions[_subscription] = (
            cb,
            self._lib.mavsdk_modes_unsubscribe_current_mode,
        )

        return _subscription

    def unsubscribe_current_mode(self, handle: ctypes.c_void_p):
        """Unsubscribe from current_mode

        Idempotent. Does nothing once the plugin is destroyed, which unsubscribes
        already.
        """
        with self._destroy_lock:
            if not self._handle:
                return
            # Holds the callback trampoline until the C unsubscribe has returned.
            _entry = self._subscriptions.pop(handle, None)
            if _entry is None:
                return
            _plugin_handle = self._handle

        self._lib.mavsdk_modes_unsubscribe_current_mode(_plugin_handle, handle)
        del _entry

    def current_mode(self):
        """Get current_mode (blocking)"""

        result_out = ModeCStruct()

        self._lib.mavsdk_modes_current_mode(
            self._require_handle(), ctypes.byref(result_out)
        )

        py_result = Mode.from_c_struct(result_out)
        self._lib.mavsdk_modes_mode_destroy(ctypes.byref(result_out))
        return py_result

    def set_mode_async(self, name, callback: Callable, user_data: Any = None):
        """Set mode by name.

        The name needs to match exactly (case-sensitive) the name of one of the available modes."""

        def c_callback(result, ud):
            try:
                py_result = ModesResult(result)

                callback(py_result, user_data)

            except Exception as e:
                print(f"Error in set_mode callback: {e}")

        cb = SetModeCallback(c_callback)
        self._callbacks.append(cb)

        self._lib.mavsdk_modes_set_mode_async(
            self._require_handle(),
            name.encode("utf-8") if isinstance(name, str) else name,
            cb,
            None,
        )

    def set_mode(self, name):
        """Get set_mode (blocking)"""

        result_code = self._lib.mavsdk_modes_set_mode(
            self._require_handle(),
            name.encode("utf-8") if isinstance(name, str) else name,
        )
        result = ModesResult(result_code)
        if result != ModesResult.SUCCESS:
            raise ModesError(result, "set_mode()", name)

        return result

    def _require_handle(self) -> ctypes.c_void_p:
        """Fail loudly rather than dereferencing a null handle in C.

        The plugin is destroyed together with its owner, which a caller holding on
        to it may not expect, so using it afterwards would otherwise segfault in
        the C wrapper.
        """
        if not self._handle:
            raise RuntimeError(
                "Modes has been destroyed (its "
                "system or "
                "Mavsdk was destroyed, or destroy() was called explicitly)"
            )
        return self._handle

    def destroy(self):
        """Destroy the plugin instance. Idempotent and safe from any thread."""
        with self._destroy_lock:
            handle, self._handle = self._handle, None
            # Taken under the same lock as the handle, so an unsubscribe racing
            # this either gets its entry and releases it itself, or finds the
            # plugin already gone. Neither path releases a handle twice.
            _subscriptions = list(self._subscriptions.items())
            self._subscriptions.clear()

        if handle:
            # The C wrapper does not track these, so release them here. unsubscribe()
            # waits for a running callback, so this cannot race one. The snapshot
            # also holds the trampolines until past destroy, so a late callback
            # cannot jump into collected memory.
            for _subscription, (_cb, _unsubscribe) in _subscriptions:
                _unsubscribe(handle, _subscription)

            self._lib.mavsdk_modes_destroy(handle)
            self._callbacks.clear()

    def __del__(self):
        self.destroy()


# ===== Callback Types =====
AvailableModesCallback = ctypes.CFUNCTYPE(
    None, ctypes.POINTER(ModeCStruct), ctypes.c_size_t, ctypes.c_void_p
)
CurrentModeCallback = ctypes.CFUNCTYPE(None, ModeCStruct, ctypes.c_void_p)
SetModeCallback = ctypes.CFUNCTYPE(None, ctypes.c_int, ctypes.c_void_p)

